class SmartLight {
  constructor(initialBrightness) {
    // TODO: Make brightnessLevel private and initialize it securely
    this.brightnessLevel = initialBrightness;
    console.log(`SmartLight created with brightness: ${this.brightnessLevel}`);
  }

  // TODO: Implement a public getter for brightness
  getBrightness() {
    return this.brightnessLevel;
  }

  // TODO: Implement a public method to set brightness, ensuring it's between 0 and 100
