    console.log(`Brightness set to: ${this.brightnessLevel}`);
  }
}

// Example Usage (should show controlled behavior)
const livingRoomLight = new SmartLight(50);
livingRoomLight.setBrightness(120); // Should be capped at 100
livingRoomLight.setBrightness(-10); // Should be floored at 0
livingRoomLight.setBrightness(75); // Should work
console.log(`Final Brightness: ${livingRoomLight.getBrightness()}`);

