class SmartLight {
  #brightnessLevel; // Private field declaration

  constructor(initialBrightness) {
    this.#brightnessLevel = 0; // Initialize private field directly
    this.setBrightness(initialBrightness); // Use the setter for initial validation
    console.log(`SmartLight created with brightness: ${this.#brightnessLevel}`);
  }

  getBrightness() {
    return this.#brightnessLevel;
  }

  setBrightness(newLevel) {
    if (newLevel < 0) {
      this.#brightnessLevel = 0;
    } else if (newLevel > 100) {
      this.#brightnessLevel = 100;
    } else {
      this.#brightnessLevel = newLevel;
    }
    console.log(`Brightness set to: ${this.#brightnessLevel}`);
  }
}

// Example Usage
const livingRoomLight = new SmartLight(50);
livingRoomLight.setBrightness(120);
livingRoomLight.setBrightness(-10);
livingRoomLight.setBrightness(75);
console.log(`Final Brightness: ${livingRoomLight.getBrightness()}`);

